class Guild:
    guild_name = "Fellowship"
    members = []

    @classmethod
    def add_member(cls, name):
        cls.members.append(name)
        print(f"{name} joined the {cls.guild_name}!")

    @classmethod
    def remove_member(cls, name):
        if name in cls.members:
            cls.members.remove(name)
            print(f"Removing {name}...")

    @classmethod
    def display_members(cls):
        return cls.members

    @staticmethod
    def validate_name(name):
        return len(name) >= 3

class GuildMember:
    def __init__(self, name, role):
        self.name = name
        self.role = role

    def join_guild(self):
        if Guild.validate_name(self.name):
            Guild.add_member(self.name)
        else:
            print(f"Invalid name: {self.name}")

# Create members
aragorn = GuildMember("Aragorn", "Fighter")
legolas = GuildMember("Legolas", "Archer")
gimli = GuildMember("Gimli", "Warrior")

# Join guild
aragorn.join_guild()
legolas.join_guild()
gimli.join_guild()

# Display
print(f"{Guild.guild_name} members: {Guild.display_members()}")

# Remove member
Guild.remove_member("Legolas")
print(f"{Guild.guild_name} members: {Guild.display_members()}")
